<template>
  <section class="notification-panel" aria-label="消息中心">
    <header class="notification-panel-header"><div><h2>消息中心</h2><p>{{notifications.unread ? `${notifications.unread} 条未读` : '提醒与公告，都在这里'}}</p></div><button class="notification-batch" type="button" :disabled="!notifications.unread" aria-label="已加载消息全部已读" title="将已加载消息标为已读" @click="notifications.markAllRead"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m3 12 4 4 9-9m-4 9 9-9"/></svg>标为已读</button></header>
    <nav class="notification-panel-filters" aria-label="消息筛选"><button v-for="tab in tabs" :key="tab.key" :aria-pressed="notifications.filter===tab.key" @click="notifications.filter=tab.key">{{tab.label}}</button></nav>
    <div v-if="notifications.error" class="notification-panel-error" role="status"><span>{{notifications.error}}</span><button type="button" v-if="notifications.errorAction==='offline'" disabled>等待联网</button><button type="button" v-else-if="notifications.errorAction!=='settings'" :disabled="notifications.refreshing" @click="notifications.refreshRemote()">{{notifications.refreshing?'正在重试…':'重试'}}</button><button v-else type="button" @click="$emit('settings')">查看连接设置</button></div>
    <div v-if="notifications.refreshing" class="notification-panel-refresh" role="status"><span class="notification-panel-spinner"/>正在刷新消息…</div>
    <div class="notification-panel-scroll" :aria-busy="notifications.refreshing||notifications.loading">
      <section v-if="(notifications.loading||notifications.refreshing)&&!notifications.items.length" class="notification-panel-empty" role="status"><span class="notification-panel-spinner"/><strong>正在加载消息</strong><p>正在获取最新提醒</p></section>
      <section v-else-if="!notifications.visible.length" class="notification-panel-empty"><svg viewBox="0 0 48 48" aria-hidden="true"><path d="M11 29h8l3 4h4l3-4h8M12 12h24l4 17v9H8v-9zM18 19h12m-12 5h8"/></svg><strong>{{notifications.filter==='unread'?'没有未读消息':'这里还没有消息'}}</strong><p>{{notifications.filter==='archive'?'归档的消息会保留在这里':'新提醒会及时出现在这里'}}</p></section>
      <div v-for="item in notifications.visible" :key="item.id" class="notification-entry" :class="{unread:!item.read}">
        <button class="notification-message" type="button" @click="$emit('open',item)"><span class="notification-entry-icon" :class="item.kind" aria-hidden="true"><svg v-if="item.kind==='task'" viewBox="0 0 24 24"><rect x="5" y="5" width="14" height="14" rx="4"/><path d="m8 12 3 3 5-6"/></svg><svg v-else-if="item.kind==='notice'" viewBox="0 0 24 24"><path d="m4 10 12-4v12L4 14zM16 10h4v4h-4M7 15l2 5h3l-2-4"/></svg><svg v-else viewBox="0 0 24 24"><path d="M19 8a8 8 0 0 0-13-3L3 8m0-5v5h5m-3 8a8 8 0 0 0 13 3l3-3m0 5v-5h-5"/></svg></span><span class="notification-entry-copy"><span class="notification-entry-title"><strong>{{item.title}}</strong><i v-if="!item.read" aria-label="未读"/></span><span class="notification-entry-summary">{{item.message}}</span><span class="notification-entry-meta"><time>{{formatTime(item.createdAt)}}</time><span>·</span><span>{{item.targetState&&item.targetState!=='active'?targetLabel(item.targetState):kindLabel(item.kind)}}</span></span></span></button>
        <button v-if="!item.archivedAt" class="notification-archive" type="button" aria-label="归档" title="归档" @click="notifications.archive(item.id)"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 9v10h14V9M4 5h16v4H4zM10 13h4"/></svg></button>
      </div>
      <button v-if="notifications.nextBefore" class="notification-panel-more" type="button" :disabled="notifications.refreshing" @click="notifications.loadMore">加载更早消息 <span aria-hidden="true">↓</span></button>
    </div>
  </section>
</template>
<script setup lang="ts">
import type {useNotificationsStore,PcNotification} from '../stores/notifications'
defineProps<{notifications:ReturnType<typeof useNotificationsStore>}>()
defineEmits<{open:[item:PcNotification];settings:[]}>()
const tabs=[{key:'all',label:'全部'},{key:'unread',label:'未读'},{key:'task',label:'任务'},{key:'notice',label:'公告'},{key:'archive',label:'已归档'}] as const
const formatTime=(value:string)=>new Date(value).toLocaleString('zh-CN',{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit',hour12:false})
const targetLabel=(state:string)=>({completed:'任务已完成',missing:'目标已删除',abandoned:'任务已放弃',rescheduled:'提醒已变更',withdrawn:'公告已撤回'} as Record<string,string>)[state]||'目标已失效'
const kindLabel=(kind:string)=>({task:'任务提醒',notice:'系统公告',sync:'同步消息',focus:'专注提醒'} as Record<string,string>)[kind]||'消息'
</script>
<style scoped>
