.notification-panel .notification-panel-header{position:static;display:flex;align-items:center;justify-content:space-between;gap:12px;padding:17px 18px 10px;border:0;background:transparent}.notification-panel-header h2{margin:0;font-size:15px;line-height:1.4;font-weight:600;letter-spacing:-.2px}.notification-panel-header p{margin:4px 0 0;color:var(--pc-muted,#748078);font-size:11px;line-height:1.5}
.notification-panel-header .notification-batch{gap:5px;padding:0 2px;color:var(--pc-primary,#245d43);font-size:11px}.notification-batch svg{width:16px;height:16px}
