.notification-entry-icon{display:grid;place-items:center;width:29px;height:29px;margin-top:1px;border-radius:9px;background:var(--pc-primary-soft,#e3efe7);color:var(--pc-primary,#245d43);flex-shrink:0}.notification-entry-icon.notice{background:#eef0f6;color:#6b7595}.notification-entry-icon.sync{background:#f4ede3;color:#9a7b4d}
.notification-entry-copy{display:flex;flex-direction:column;gap:5px;min-width:0;flex:1}.notification-entry-title{display:flex;align-items:center;gap:6px}.notification-entry-title strong{font-size:12px;line-height:1.5;font-weight:550;color:var(--pc-text,#17201b);overflow-wrap:anywhere}.notification-entry-title i{width:5px;height:5px;border-radius:50%;background:var(--pc-primary,#245d43);flex-shrink:0}
.notification-entry-summary{display:-webkit-box;overflow:hidden;-webkit-line-clamp:2;-webkit-box-orient:vertical;font-size:11px;line-height:1.6;color:#69766e;overflow-wrap:anywhere}.notification-entry-meta{display:flex;flex-wrap:wrap;align-items:center;gap:5px;margin-top:1px;font-size:10px;line-height:1.5;color:var(--pc-muted,#748078)}.notification-entry-meta time{font-size:inherit;color:inherit}
.notification-panel .notification-archive{width:28px;min-height:32px;margin:10px -4px 0 3px;color:var(--pc-muted,#748078);opacity:.5}.notification-archive svg{width:15px;height:15px}.notification-entry:hover .notification-archive,.notification-archive:focus-visible{opacity:1}.notification-panel .notification-archive:hover{background:var(--pc-primary-soft,#e3efe7);color:var(--pc-primary,#245d43)}
.notification-panel-refresh{display:flex;align-items:center;gap:8px;padding:10px 18px;color:var(--pc-primary);font-size:12px}.notification-panel-refresh .notification-panel-spinner{width:14px;height:14px;margin:0}
.notification-panel-error{display:flex;align-items:center;gap:10px;margin:10px 17px 0;padding:7px 9px;border-radius:7px;background:#f6f0e7;color:#8b6c40;font-size:11px;line-height:1.5}.notification-panel-error>span{flex:1;min-width:0}.notification-panel-error button{flex-shrink:0;font-size:11px;color:inherit}
.notification-panel-empty{display:flex;flex-direction:column;align-items:center;gap:8px;min-height:210px;padding:44px 15px 32px;text-align:center}.notification-panel-empty>svg{width:39px;height:39px;margin-bottom:5px;color:#a1b0a6;stroke-width:1.2}.notification-panel-empty strong{font-size:12px;font-weight:500}.notification-panel-empty p{margin:0;font-size:11px;color:var(--pc-muted,#748078)}
.notification-panel-spinner{width:21px;height:21px;margin:0 0 12px;border:2px solid var(--pc-border,#e3e9e3);border-top-color:var(--pc-primary,#245d43);border-radius:50%;animation:notification-spin .8s linear infinite}@keyframes notification-spin{to{transform:rotate(360deg)}}.notification-panel .notification-panel-more{display:flex;gap:7px;width:100%;margin:4px 0 0;padding:7px 0;color:var(--pc-muted,#748078);font-size:11px}
@media(prefers-reduced-motion:reduce){.notification-panel-spinner{animation:none}}
</style>
